    [2637] = { objectivesES = {
        "Entra en los Ettenmoors y busca uno de los puestos de avanzada allí. Estos se pueden encontrar en el lejano suroeste, con vistas al río cerca de Hoarhallow, el cercano suroeste justo más allá del río y al norte cerca de la entrada occidental de la mina Isendeep.",
        "Te han encargado capturar un puesto en los Ettenmoors. Deberías regresar a Akulhún, el tirador de guerra, cuando esto esté completo.",
        "* Capture un puesto de avanzada en los Ettenmoors",
        "El puesto de avanzada es reclamado por Angmar, regresar a Akulhún en Gramsfoot y decirle su victoria.",
        "* Regresar a Akulhún, el teniente de guerra, en Gramsfoot",
    } },
    [2638] = { objectivesES = {
        "Entra en los Ettenmoors y busca uno de los puestos de avanzada allí. Estos se pueden encontrar en el lejano suroeste, con vistas al río cerca de Hoarhallow, el cercano suroeste justo más allá del río y al norte cerca de la entrada occidental de la mina Isendeep.",
        "Te han encargado capturar un puesto en los Ettenmoors. Debe regresar al Capitán General Tordúr cuando esto esté completo.",
        "* Capture un puesto de avanzada en los Ettenmoors",
        "El puesto de avanzada se reclama para el pueblo libre, regresa a Glân Vraig e informa al Capitán General Tordúr de su victoria.",
        "* Volver al capitán general Tordúr en Glân Vraig",
    } },
    [2643] = { objectivesES = {
