    [3582] = { objectivesES = {
        "Haga su camino a Grothum y hable con el líder Bok para aprender cómo los duendes irían pervirtiendo el orden natural que crecería este azote.",
        "* Habla con Bok en Grothum",
        "Entra en los Ettenmoors y caza a cualquiera de los guardias populares libres allí. Es probable que lleven aceite que se pueda utilizar para envenenar las raíces del azote. Reemplaza el agua con aceite y observa que el azote se vuelve rancio.",
    } },
    [3583] = { objectivesES = {
        "Haga su camino a Grothum y pida a Tyrant Búrzgoth orientación sobre cómo corromper el azote.",
        "* Habla con Tyrant Búrzgoth en Grothum",
        "Búrzgoth sugirió matar osos por sus halzones y darles de comer a su amontonamiento... no una idea terrible de un troll.",
        "* Entrega antorchas de Morningthaw a Cinaid en Gramsfoot",
    } },
    [3584] = { objectivesES = {
        "Cinaid te envió a los Ettenmoors para apuntar a lugares a lo largo del Hoardale donde la gente libre busca recoger agua pura. Vas a arrasar el agua con veneno para frustrar los diseños del pueblo libre.",
        "El agua está envenenada y cualquier recogido aquí seguramente no ayudará en el crecimiento puro de nada que alimenta. Vuelva a Cinaid en Gramsfoot y dígale su éxito.",
    } },
    [3585] = { objectivesES = {
        "Cinaid te dirigió a recoger barbas enanas para utilizar en la creación de un proceso de crecimiento doloroso para tu azote para que aprenda el olor del enano y lo asocie con el dolor de su crecimiento adolescente.",
    } },
    [3586] = { objectivesES = {
        "Cinaid te sugirió ir a Hithlad y destruir criaturas de la naturaleza allí. El potencial de la risa sería aliados a su azote.",
        "* Slaughter Leafcull Bog-lurkers",
        "Con los lurkers derrotados deberías regresar a Cinaid y decirles de tus esfuerzos.",
        "* Habla con Cinaid en Gramsfoot",
    } },
    [3588] = { objectivesES = {
        "Haga su camino a las aguas que rodean Tol Ascarnen y mate al presente Nerbyg para asegurar que su presencia natural se disminuya y no puede llamar a su sapling.",
        "* Matar a Nerbyg cerca de Tol Ascarnen",
        "Ahora que el Nerbyg que quería muerto se retiran, regresan a Cinaid en Gramsfoot y les informan de las noticias.",
        "* Habla con Cinaid en Gramsfoot",
    } },
    [3589] = { objectivesES = {
        "Cinaid te pidió que recogieras las piernas de los hombres para meterte en el suelo que alimenta tu azote. Conseguir el sabor de la sangre de los hombres contaminará el azote.",
    } },
    [3590] = { objectivesES = {
