    [6652] = { objectivesES = {
        "Keteph le pidió que llevara sus entregas a los eruditos y artesanos ocupados en el campo de expedición al sureste de Umbar Baharbêl. La mayoría son empleados de los aristócratas que serán los árbitros finales de su última creación.",
        "No recibió más que buena voluntad y palabras de aliento de los habitantes del campo de expedición. Parece que la receta de Keteph está completa. Regresa a él en la Guild-hall de Swain en Umbar Baharbêl.",
    } },
    [6653] = { objectivesES = {
