    [13736] = { objectivesES = {
        "Enviar un montón de patrones aleatorios de humo confundirá las naves corsair.",
        "* Señales de humo enviados",
    } },
    [13737] = { objectivesES = {
        "Las jaulas se pueden encontrar en las costas de Tol Fennas.",
        "Dimlas te pidió que liberaras animales de jaulas en Tol Fennas. Un barco en el puerto de Dol Amroth puede llevarte a Tol Fennas.",
        "* Cages destructoras",
        "Dimlas está en Dol Amroth.",
        "Dimlas estará encantado de escucharte liberar muchos animales.",
    } },
    [13739] = { objectivesES = {
        "Los barcos se pueden encontrar en Makham Jurrar, el campo de madera y astillero en el lado norte de Tol Fennas.",
        "Glíreth le pidió que se aventurase a Tol Fennas y destruir los barcos que se construyen allí. Un barco en el puerto de Dol Amroth puede llevarte a Tol Fennas.",
        "* Barcos destructivos en Makham Jurrar",
        "Glíreth está en Dol Amroth.",
        "Glíreth estará encantado de escuchar que los barcos de Makham Jurrar han sido destruidos.",
